/**
 * Parse SERP Data — SerpAPI 결과 구조화 추출
 * Mode: runOnceForEachItem
 * 입력: SerpAPI JSON 응답 (각 아이템)
 * 출력: 구조화된 SERP 텍스트 (프롬프트에 삽입용)
 */

const serpResults = $input.item.json;

// 1. Organic Results (상위 7개) — 제목, 스니펫, URL
let organicText = '';
const serpUrls = [];
if (serpResults.organic_results && serpResults.organic_results.length > 0) {
  const top7 = serpResults.organic_results.slice(0, 7);
  organicText = top7.map((r, i) =>
    `${i + 1}. ${r.title}\n   ${r.snippet || '(스니펫 없음)'}\n   URL: ${r.link || ''}`
  ).join('\n');
  for (const r of top7) {
    if (r.link) serpUrls.push(r.link);
  }
}

// 2. People Also Ask (관련 질문, 5개) — FAQ 재료
let paaText = '';
if (serpResults.related_questions && serpResults.related_questions.length > 0) {
  const top5 = serpResults.related_questions.slice(0, 5);
  paaText = top5.map((q, i) =>
    `${i + 1}. ${q.question}${q.snippet ? '\n   → ' + q.snippet : ''}`
  ).join('\n');
}

// 3. Related Searches (관련 검색어, 8개) — internal_link_keywords 후보
let relatedText = '';
if (serpResults.related_searches && serpResults.related_searches.length > 0) {
  const top8 = serpResults.related_searches.slice(0, 8);
  relatedText = top8.map(r => r.query).join(', ');
}

// 4. Knowledge Graph (있으면) — 정의 앵커
let kgText = '';
if (serpResults.knowledge_graph) {
  const kg = serpResults.knowledge_graph;
  kgText = `${kg.title || ''}: ${kg.description || kg.snippet || ''}`;
  if (kg.source) {
    kgText += ` (출처: ${kg.source.name || ''})`;
  }
  // Extract knowledge graph URL
  if (kg.source && kg.source.link) {
    serpUrls.push(kg.source.link);
  }
}

// 구조화된 SERP 텍스트 조합
const sections = [];

if (organicText) {
  sections.push(`### 검색 상위 콘텐츠 (상위 7개)\n${organicText}`);
}
if (paaText) {
  sections.push(`### People Also Ask (사람들이 자주 묻는 질문)\n${paaText}`);
}
if (relatedText) {
  sections.push(`### 관련 검색어\n${relatedText}`);
}
if (kgText) {
  sections.push(`### 지식 그래프 정의\n${kgText}`);
}

const serpText = sections.length > 0
  ? sections.join('\n\n')
  : '(SERP 데이터 없음)';

// 시트 데이터를 함께 전달
const sheetData = $('Sheets Read (Status=대기)').item.json;

return {
  json: {
    ...sheetData,
    serp_text: serpText,
    serp_urls: serpUrls,
    serp_organic_count: serpResults.organic_results ? serpResults.organic_results.length : 0,
    serp_paa_count: serpResults.related_questions ? serpResults.related_questions.length : 0,
    serp_related_count: serpResults.related_searches ? serpResults.related_searches.length : 0,
    serp_has_kg: !!serpResults.knowledge_graph,
  }
};

/**
 * Build LLM Request — provider별 URL/headers/body 생성
 * 입력: system_prompt, user_message, _llm_purpose(optional)
 * 출력: _llm_url, _llm_headers, _llm_body, _llm_provider + 원본 데이터 패스스루
 */

const provider = $env.LLM_PROVIDER || 'gemini';
const systemPrompt = $input.item.json.system_prompt;
const userMessage = $input.item.json.user_message;
const purpose = $input.item.json._llm_purpose || 'content_gen';

const PROVIDERS = {
  gemini: {
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${$env.GOOGLE_API_KEY}`,
    headers: { 'content-type': 'application/json' },
    body: (sys, user, opts) => ({
      contents: [{ role: 'user', parts: [{ text: user }] }],
      systemInstruction: { parts: [{ text: sys }] },
      generationConfig: { maxOutputTokens: opts.maxTokens, temperature: opts.temperature }
    }),
  },
  claude: {
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.CLAUDE_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: (sys, user, opts) => ({
      model: opts.model || 'claude-sonnet-4-5-20250514',
      max_tokens: opts.maxTokens,
      temperature: opts.temperature,
      system: sys,
      messages: [{ role: 'user', content: user }],
    }),
  },
};

const config = PROVIDERS[provider];
if (!config) throw new Error(`지원하지 않는 LLM provider: ${provider}`);

const opts = purpose === 'verification'
  ? { maxTokens: 800, temperature: 0, model: 'claude-haiku-4-5-20251001' }
  : { maxTokens: 32768, temperature: 0.7 };

return {
  json: {
    _llm_url: config.url,
    _llm_headers: config.headers,
    _llm_body: config.body(systemPrompt, userMessage, opts),
    _llm_provider: provider,
    ...Object.fromEntries(
      Object.entries($input.item.json).filter(([k]) => !k.startsWith('_llm'))
    ),
  }
};

/**
 * Normalize LLM Response — provider별 응답에서 텍스트 추출
 * Gemini: candidates[0].content.parts[0].text
 * Claude: content[0].text
 */

const provider = $input.item.json._llm_provider
  || $env.LLM_PROVIDER
  || 'gemini';

let text;
const data = $input.item.json;

if (provider === 'gemini') {
  text = data.candidates[0].content.parts[0].text;
} else if (provider === 'claude') {
  text = data.content[0].text;
} else {
  throw new Error(`지원하지 않는 provider 응답: ${provider}`);
}

return { json: { text, _llm_provider: provider } };

/**
 * Node 6: LLM 응답 JSON 파싱 + 필수 필드 검증
 * Mode: runOnceForEachItem
 * 입력: 정규화된 LLM 응답 (text)
 * 출력: 파싱된 JSON 또는 에러
 *
 * LLM이 생성한 JSON의 일반적 문제를 자동 복구:
 * - 문자열 내 이스케이프되지 않은 " (YAML, 코드블록 등)
 * - 제어 문자 (raw newline/tab)
 * - 유효하지 않은 이스케이프 시퀀스 (\g, \e 등)
 */

const raw = $input.item.json.text;

// === Step 1: JSON 블록 추출 ===
let jsonStr;
const fenceStart = raw.indexOf('```json');
if (fenceStart !== -1) {
  const contentStart = raw.indexOf('\n', fenceStart);
  const fenceEnd = raw.lastIndexOf('```');
  if (contentStart !== -1 && fenceEnd > fenceStart + 7) {
    jsonStr = raw.substring(contentStart + 1, fenceEnd).trim();
  }
}
if (!jsonStr) {
  const match = raw.match(/(\{[\s\S]*\})/);
  if (!match) {
    throw new Error("JSON 추출 실패: " + raw.substring(0, 200));
  }
  jsonStr = match[1];
}

// === Step 2: Lenient JSON repair ===
// 구조적 파싱으로 이스케이프되지 않은 " 와 제어 문자를 자동 복구
function repairJson(str) {
  const VALID_ESCAPES = '"\\\/bfnrtu';
  let result = '';
  let i = 0;

  function skipWS() {
    while (i < str.length && /\s/.test(str[i])) { result += str[i++]; }
  }

  function parseValue() {
    skipWS();
    if (i >= str.length) return;
    if (str[i] === '"') parseString();
    else if (str[i] === '{') parseObject();
    else if (str[i] === '[') parseArray();
    else parseLiteral();
  }

  function parseString() {
    result += str[i++]; // opening "

    while (i < str.length) {
      const ch = str[i];

      // 이스케이프 시퀀스
      if (ch === '\\' && i + 1 < str.length) {
        const next = str[i + 1];
        if (VALID_ESCAPES.includes(next)) {
          result += ch + next;
        } else {
          // 유효하지 않은 이스케이프 → 백슬래시 이중 이스케이프
          result += '\\\\' + next;
        }
        i += 2;
        continue;
      }

      // 큰따옴표: 구조적 종료인지 content 내 인용부호인지 판단
      if (ch === '"') {
        // 다음 비공백 문자로 판단
        let peek = i + 1;
        while (peek < str.length && /[\s\n\r\t]/.test(str[peek])) peek++;

        if (peek >= str.length || ',:]}'.indexOf(str[peek]) !== -1) {
          // 구조적 종료: 뒤에 , ] } : 또는 EOF
          result += '"';
          i++;
          return;
        } else if (str[peek] === '"') {
          // 다음도 " → 다음 " 뒤에 : 이 있으면 객체 키 → 구조적 종료
          let j = peek + 1;
          while (j < str.length && str[j] !== '"' && str[j] !== ':') j++;
          if (j < str.length && str[j] === ':') {
            // "value" "key": → 쉼표 누락이지만 구조적 종료
            result += '"';
            i++;
            return;
          }
          // 다음 " 뒤에 : 없음 → content 내 인용부호
          result += '\\"';
          i++;
          continue;
        } else {
          // 뒤에 일반 문자 → content 내 이스케이프되지 않은 인용부호
          result += '\\"';
          i++;
          continue;
        }
      }

      // 제어 문자
      const code = ch.charCodeAt(0);
      if (code <= 0x1f) {
        if (code === 0x0a) result += '\\n';
        else if (code === 0x0d) result += '\\r';
        else if (code === 0x09) result += '\\t';
        i++;
        continue;
      }

      result += ch;
      i++;
    }
  }

  function parseObject() {
    result += str[i++]; // {
    skipWS();
    let first = true;
    while (i < str.length && str[i] !== '}') {
      if (!first) {
        if (str[i] === ',') result += str[i++];
        // 쉼표 누락: "}" 아닌 다른 문자가 오면 쉼표 삽입
        else {
          skipWS();
          if (i < str.length && str[i] === '"') result += ',';
        }
      }
      first = false;
      skipWS();
      if (i >= str.length || str[i] === '}') break;
      parseString(); // key
      skipWS();
      if (i < str.length && str[i] === ':') result += str[i++];
      parseValue();   // value
      skipWS();
    }
    if (i < str.length && str[i] === '}') result += str[i++];
  }

  function parseArray() {
    result += str[i++]; // [
    skipWS();
    let first = true;
    while (i < str.length && str[i] !== ']') {
      if (!first) {
        if (str[i] === ',') result += str[i++];
        else {
          skipWS();
          if (i < str.length && str[i] !== ']') result += ',';
        }
      }
      first = false;
      skipWS();
      if (i >= str.length || str[i] === ']') break;
      parseValue();
      skipWS();
    }
    if (i < str.length && str[i] === ']') result += str[i++];
  }

  function parseLiteral() {
    // number, boolean, null
    while (i < str.length && /[^\s,\]}\[]/.test(str[i])) {
      result += str[i++];
    }
  }

  parseValue();
  return result;
}

// === Step 3: 파싱 ===
let parsed;

// 1차: 그대로 파싱
try {
  parsed = JSON.parse(jsonStr);
} catch (e1) {
  // 2차: lenient repair 후 파싱
  try {
    const repaired = repairJson(jsonStr);
    parsed = JSON.parse(repaired);
  } catch (e2) {
    throw new Error("JSON 파싱 실패: " + e1.message + " | repair 후: " + e2.message);
  }
}

// === Step 4: 필수 필드 검증 ===
const required = ["title", "content", "meta_description", "faq_schema",
                  "references", "internal_link_keywords"];
const missing = required.filter(f => !parsed[f]);
if (missing.length > 0) {
  throw new Error("필수 필드 누락: " + missing.join(", "));
}

// meta_description 길이 검증 (120~155자)
const metaLen = parsed.meta_description.length;
if (metaLen < 120 || metaLen > 155) {
  parsed._warning = `meta_description 길이: ${metaLen}자 (권장 120~155자)`;
}

// faq_schema 형식 검증
if (!Array.isArray(parsed.faq_schema) || parsed.faq_schema.length === 0) {
  throw new Error("faq_schema가 비어있거나 배열이 아닙니다");
}
for (const faq of parsed.faq_schema) {
  if (!faq.question || !faq.answer) {
    throw new Error("faq_schema 항목에 question/answer 누락");
  }
}

// 본문 길이 검증 (프롬프트 유형별 최소 글자 수)
const promptType = $('Route Prompt (A/B/C)').item.json.prompt_type || 'A';
const LENGTH_RULES = {
  'A': { min: 1500 },
  'B': { min: 2000 },
  'C': { min: 2000 }
};
const rule = LENGTH_RULES[promptType] || LENGTH_RULES['A'];
if (parsed.content.length < rule.min) {
  throw new Error(`본문 길이 부족: ${parsed.content.length}자 (최소 ${rule.min}자, 유형: ${promptType})`);
}

return { json: parsed };

/**
 * Inject Images — Mermaid 다이어그램 → kroki.io URL + Unsplash Hero/섹션 이미지 + 썸네일
 * Mode: runOnceForEachItem
 * Parse JSON Response와 Validate Structure 사이에 배치
 * 입력: 파싱된 JSON (content 필드 포함)
 * 출력: [MERMAID]→kroki.io <img> URL 변환된 content + <!-- IMAGE: -->→Unsplash <figure>
 *       + Hero 이미지 + thumbnail_url + image_injection 메타데이터
 *
 * LLM은 [MERMAID]...[/MERMAID] 커스텀 마커로 다이어그램을 생성한다.
 * (JSON 안의 ```가 fence 탐지를 깨뜨리고 Gemini 응답 truncation을 유발하는 것을 방지)
 * SVG를 직접 삽입하지 않고 kroki.io GET URL을 사용하여 Google Sheets 50K 셀 제한을 회피한다.
 * 다이어그램당 URL ~200자 vs 인라인 SVG ~10,000자+
 *
 * <!-- IMAGE: keyword --> 마커는 LLM이 콘텐츠 맥락에 맞게 생성하며,
 * Unsplash API로 검색하여 <figure> 태그로 치환한다.
 */

const zlib = require('zlib');

const content = $input.item.json.content || '';
const title = $input.item.json.title || '';
const UNSPLASH_KEY = $env.UNSPLASH_ACCESS_KEY;
const helpers = this.helpers;

const MAX_SECTION_IMAGES = 2;

/**
 * IT 기술 키워드 → Unsplash 검색 친화 키워드 매핑
 * thumbnail/hero 검색용으로 유지
 */
const KEYWORD_BROADENING = {
  terraform: 'cloud infrastructure automation',
  ansible: 'server automation terminal',
  jenkins: 'software development pipeline',
  kubernetes: 'cloud container technology',
  docker: 'container technology server',
  'ci/cd': 'software deployment automation',
  cicd: 'software deployment automation',
  ssl: 'cybersecurity encryption lock',
  tls: 'cybersecurity encryption lock',
  siem: 'cybersecurity monitoring dashboard',
  splunk: 'data analytics dashboard',
  elk: 'data analytics search',
  prometheus: 'server monitoring dashboard',
  grafana: 'monitoring dashboard visualization',
  dns: 'network technology server',
  vpn: 'network security connection',
  saml: 'authentication security login',
  oauth: 'authentication security login',
  iam: 'identity access management security',
  mfa: 'two factor authentication security',
  'sd-wan': 'network infrastructure',
  microservice: 'software architecture diagram',
  'zero trust': 'cybersecurity network',
  iac: 'infrastructure as code automation',
};

/**
 * Unsplash API에서 이미지 검색
 * @param {string} keyword - 검색 키워드
 * @param {Set<string>} usedIds - 같은 글 내 사진 중복 방지용 ID Set
 * @returns {object|null} { id, thumb, url, photographer, photographerUrl }
 */
async function searchUnsplash(keyword, usedIds) {
  if (!UNSPLASH_KEY) return null;

  try {
    const data = await helpers.httpRequest({
      method: 'GET',
      url: 'https://api.unsplash.com/search/photos',
      qs: {
        query: keyword,
        orientation: 'landscape',
        per_page: '10',
        client_id: UNSPLASH_KEY,
      },
    });
    if (!data.results || data.results.length === 0) return null;

    // usedIds에 없는 사진 중 랜덤 선택
    const available = data.results.filter(p => !usedIds.has(p.id));
    if (available.length === 0) return null;

    const idx = Math.floor(Math.random() * Math.min(available.length, 6));
    const photo = available[idx];

    return {
      id: photo.id,
      thumb: photo.urls.small,
      url: photo.urls.regular,
      photographer: photo.user.name || 'Unknown',
      photographerUrl: photo.user.links?.html || 'https://unsplash.com',
    };
  } catch (e) {
    return null;
  }
}

/**
 * Unsplash 이미지를 <figure> 태그로 생성
 * @param {object} photo - searchUnsplash 반환값
 * @param {string} altText - alt 속성 텍스트
 * @param {boolean} isHero - Hero 이미지 여부 (fetchpriority="high")
 * @returns {string} <figure> HTML
 */
function unsplashFigureTag(photo, altText, isHero) {
  const safeAlt = altText.replace(/"/g, '&quot;');
  const priority = isHero ? ' fetchpriority="high"' : ' loading="lazy"';
  const imgUrl = isHero ? photo.url : photo.url;
  return (
    `<figure style="max-width:100%;border-radius:8px;margin:24px 0;">` +
    `<img src="${imgUrl}" alt="${safeAlt}"${priority} decoding="async" ` +
    `style="max-width:100%;height:auto;border-radius:8px;" />` +
    `<!-- Photo by ${photo.photographer} on Unsplash -->` +
    `</figure>`
  );
}

/**
 * 제목에서 Unsplash 검색용 키워드 후보 배열 생성 (hero/thumbnail용)
 */
function extractThumbnailKeywords() {
  const candidates = [];

  const titleEng = title.match(/[A-Za-z0-9][\w./-]*/g) || [];
  if (titleEng.length > 0) {
    candidates.push(titleEng.join(' '));
  }

  const lowerTitle = title.toLowerCase();
  for (const [tech, broad] of Object.entries(KEYWORD_BROADENING)) {
    if (lowerTitle.includes(tech)) {
      candidates.push(broad);
      break;
    }
  }

  candidates.push('technology software development');
  return candidates;
}

/**
 * Mermaid 코드를 kroki.io GET URL로 변환
 * deflate 압축 + base64url 인코딩 → https://kroki.io/mermaid/svg/{encoded}
 * Google Sheets 50K 제한 회피를 위해 SVG 임베딩 대신 URL 참조 사용
 * @param {string} code - Mermaid 코드 (``` 제외)
 * @returns {string|null} kroki.io URL 또는 null
 */
function mermaidToKrokiUrl(code) {
  try {
    const deflated = zlib.deflateSync(Buffer.from(code, 'utf-8'));
    const encoded = deflated.toString('base64url');
    return `https://kroki.io/mermaid/svg/${encoded}`;
  } catch (e) {
    return null;
  }
}

/**
 * Mermaid 코드를 <img> 태그로 변환 (kroki.io GET URL 참조)
 * @param {string} code - Mermaid 코드
 * @param {string} altText - alt 속성 텍스트
 * @returns {string|null} <img> 태그 또는 null
 */
function mermaidToImgTag(code, altText) {
  const url = mermaidToKrokiUrl(code);
  if (!url) return null;
  const safeAlt = altText.replace(/"/g, '&quot;');
  return `<img src="${url}" alt="${safeAlt}" width="800" height="auto" style="max-width:100%;height:auto;margin:16px 0;" />`;
}

// 글 내 Unsplash 이미지 중복 방지용 Set
const usedPhotoIds = new Set();
let unsplashApiCalls = 0;

// === Step 1: [MERMAID]...[/MERMAID] 마커 추출 ===
// LLM이 JSON 안에서 ```mermaid 대신 [MERMAID]...[/MERMAID] 마커를 사용하도록 지시됨
// (JSON fence 충돌 및 Gemini 응답 truncation 방지)
const mermaidRegex = /\[MERMAID\]([\s\S]*?)\[\/MERMAID\]/g;
const blocks = [];
let match;

while ((match = mermaidRegex.exec(content)) !== null) {
  blocks.push({
    full: match[0],
    code: match[1].trim(),
    index: match.index,
  });
}

let updatedContent = content;
let renderedCount = 0;
let failedCount = 0;

// === Step 2: 각 [MERMAID] 블록 → kroki.io URL <img> 태그 (역순 치환) ===
for (let i = blocks.length - 1; i >= 0; i--) {
  const block = blocks[i];
  const firstLine = block.code.split('\n')[0].trim();
  const altText = `Mermaid diagram: ${firstLine}`;
  const imgTag = mermaidToImgTag(block.code, altText);

  if (imgTag) {
    updatedContent =
      updatedContent.substring(0, block.index) +
      '\n' + imgTag + '\n' +
      updatedContent.substring(block.index + block.full.length);
    renderedCount++;
  } else {
    // URL 생성 실패 시 원본 코드블록 유지 (graceful degradation)
    failedCount++;
  }
}

// === Step 3: <!-- IMAGE: keyword --> 마커 → Unsplash <figure> (역순 치환) ===
const imageMarkerRegex = /<!-- IMAGE:\s*(.+?)\s*-->/g;
const imageMarkers = [];

while ((match = imageMarkerRegex.exec(updatedContent)) !== null) {
  imageMarkers.push({
    full: match[0],
    keyword: match[1].trim(),
    index: match.index,
  });
}

let sectionImagesInjected = 0;

for (let i = imageMarkers.length - 1; i >= 0; i--) {
  const marker = imageMarkers[i];

  if (sectionImagesInjected >= MAX_SECTION_IMAGES) {
    // 초과분은 마커만 제거
    updatedContent =
      updatedContent.substring(0, marker.index) +
      updatedContent.substring(marker.index + marker.full.length);
    continue;
  }

  unsplashApiCalls++;
  const photo = await searchUnsplash(marker.keyword, usedPhotoIds);

  if (photo) {
    usedPhotoIds.add(photo.id);
    const figureTag = unsplashFigureTag(photo, marker.keyword, false);
    updatedContent =
      updatedContent.substring(0, marker.index) +
      '\n' + figureTag + '\n' +
      updatedContent.substring(marker.index + marker.full.length);
    sectionImagesInjected++;
  } else {
    // 실패 시 마커 제거 (graceful degradation)
    updatedContent =
      updatedContent.substring(0, marker.index) +
      updatedContent.substring(marker.index + marker.full.length);
  }
}

// === Step 4: Hero 이미지 + thumbnail_url — Unsplash 검색 ===
let thumbnailUrl = '';
let hasHeroImage = false;

if (UNSPLASH_KEY) {
  const keywords = extractThumbnailKeywords();
  for (const kw of keywords) {
    unsplashApiCalls++;
    const result = await searchUnsplash(kw, usedPhotoIds);
    if (result) {
      usedPhotoIds.add(result.id);

      // Hero: 첫 H2 앞에 <figure> 삽입
      const firstH2 = updatedContent.match(/^## /m);
      if (firstH2) {
        const h2Index = updatedContent.indexOf(firstH2[0]);
        const heroFigure = unsplashFigureTag(result, title, true);
        updatedContent =
          updatedContent.substring(0, h2Index) +
          heroFigure + '\n\n' +
          updatedContent.substring(h2Index);
        hasHeroImage = true;
      }

      // Thumbnail: small URL (OG 이미지)
      thumbnailUrl = result.thumb;
      break;
    }
  }
}

return {
  json: {
    ...$input.item.json,
    content: updatedContent,
    thumbnail_url: thumbnailUrl,
    image_injection: {
      method: 'hybrid_mermaid_unsplash',
      mermaid_found: blocks.length,
      mermaid_rendered: renderedCount,
      mermaid_failed: failedCount,
      section_images_injected: sectionImagesInjected,
      has_hero_image: hasHeroImage,
      unsplash_api_calls: unsplashApiCalls,
      has_unsplash_key: !!UNSPLASH_KEY,
    },
  },
};

/**
 * Validate Structure — 마크다운 구조 자동 검증
 * Mode: runOnceForEachItem
 * Parse JSON과 Gemini Verification 사이에 배치
 * 입력: 파싱된 JSON (content 필드 포함)
 * 출력: 구조 검증 결과 추가
 */

const content = $input.item.json.content || '';
const promptType = $('Route Prompt (A/B/C)').item.json.prompt_type || 'A';

const issues = [];

// 0. Content length check
const MIN_CONTENT_LENGTH = 3000;
if (content.length < MIN_CONTENT_LENGTH) {
  issues.push(`본문 길이 부족: ${content.length}자 (최소 ${MIN_CONTENT_LENGTH}자)`);
}

// 1. H2 헤딩 카운트
const h2Matches = content.match(/^## /gm) || [];
const h2Count = h2Matches.length;

const MIN_H2 = { 'A': 4, 'B': 5, 'C': 4 };
const minH2 = MIN_H2[promptType] || 4;

if (h2Count < minH2) {
  issues.push(`H2 헤딩 부족: ${h2Count}개 (최소 ${minH2}개)`);
}

// 2. H3 헤딩 카운트
const h3Matches = content.match(/^### /gm) || [];
const h3Count = h3Matches.length;

// 3. 마크다운 테이블 행 수
const tableRows = content.match(/^\|.*\|$/gm) || [];
const tableSeparators = content.match(/^\|[\s\-:|]+\|$/gm) || [];
const tableDataRows = tableRows.length - tableSeparators.length;

if (promptType === 'A' || promptType === 'B') {
  if (tableDataRows < 1) {
    issues.push('마크다운 테이블 없음 (최소 1개 필요)');
  }
  if (promptType === 'B' && tableDataRows < 7) {
    issues.push(`비교표 행 부족: ${tableDataRows}행 (최소 7행)`);
  }
}

// 4. 코드블록 수
const codeBlocks = content.match(/```\w*/g) || [];
const codeBlockCount = Math.floor(codeBlocks.length / 2);

if (promptType === 'C' && codeBlockCount < 3) {
  issues.push(`코드블록 부족: ${codeBlockCount}개 (최소 3개)`);
}

// 5. FAQ 섹션 존재 여부
const hasFAQ = /##\s*FAQ/i.test(content) || /##.*자주\s*묻는/i.test(content);
if (!hasFAQ) {
  issues.push('FAQ 섹션 없음');
}

// 6. faq_schema 검증
const faqSchema = $input.item.json.faq_schema || [];
if (faqSchema.length < 3) {
  issues.push(`FAQ 항목 부족: ${faqSchema.length}개 (최소 3개)`);
}
const shortAnswers = faqSchema.filter(f => f.answer && f.answer.length < 80);
if (shortAnswers.length > 0) {
  issues.push(`FAQ 답변 80자 미만: ${shortAnswers.length}건`);
}

// 7. IMAGE 마커 잔류 검사 (inject_images.js 이후이므로 잔류하면 안됨)
const imageMarkers = content.match(/<!-- IMAGE:\s*.+?\s*-->/g) || [];
if (imageMarkers.length > 0) {
  issues.push(`미처리 IMAGE 마커 ${imageMarkers.length}개 잔류`);
}

// 8. 이미지 개수 (마크다운 + HTML img 포함)
const imageCount = (content.match(/!\[.*?\]\(.*?\)/g) || []).length;
const htmlImageCount = (content.match(/<img\s/g) || []).length;

// 8-1. image_injection 메타데이터에서 섹션/히어로 정보 추출
const imageInjection = $input.item.json.image_injection || {};
const sectionImages = imageInjection.section_images_injected || 0;
const hasHeroImage = imageInjection.has_hero_image || false;

// 9. Mermaid 마커 잔류 감지 (WARNING only — hard fail 아님)
// [MERMAID] 잔류 > 0이면 inject_images.js가 렌더링 실패한 것
// 콘텐츠 자체는 유효하므로 warning only
const mermaidResidues = content.match(/\[MERMAID\]/g) || [];
const mermaidWarning = mermaidResidues.length > 0
  ? `Mermaid 마커 ${mermaidResidues.length}개 미렌더링 (경고)`
  : null;

const passed = issues.length === 0;

return {
  json: {
    ...$input.item.json,
    structure_validation: {
      passed,
      h2_count: h2Count,
      h3_count: h3Count,
      table_rows: tableDataRows,
      code_block_count: codeBlockCount,
      has_faq_section: hasFAQ,
      faq_count: faqSchema.length,
      image_count: imageCount,
      html_image_count: htmlImageCount,
      section_images: sectionImages,
      has_hero_image: hasHeroImage,
      mermaid_residue: mermaidResidues.length,
      mermaid_warning: mermaidWarning,
      issues,
    }
  }
};

/**
 * Node 7a: URL 검증 — HTTP HEAD + SERP 교차 대조 + 죽은 URL 자동 제거
 * Mode: runOnceForEachItem
 *
 * 주의: serp_urls는 Normalize Response/Parse JSON에서 소실되므로
 *       $('Parse SERP Data') 노드에서 직접 참조한다.
 */

const helpers = this.helpers;
const item = $input.item.json;
const content = item.content || '';
const references = item.references || [];

// serp_urls는 파이프라인 중간에서 소실 → Parse SERP Data 노드에서 직접 참조
let serpUrls = [];
try {
  serpUrls = $('Parse SERP Data').item.json.serp_urls || [];
} catch { /* 노드 미존재 시 빈 배열 */ }

// URL 추출 (trailing punctuation 제거)
const urlRegex = /https?:\/\/[^\s\)\]"'<>]+/g;
const rawUrls = content.match(urlRegex) || [];
const contentUrls = rawUrls.map(u => u.replace(/[.,;:!?)]+$/, ''));

// 모든 고유 URL 수집 (content + references)
const allUrls = [...new Set([
  ...contentUrls,
  ...references.filter(r => r.startsWith('http')),
])];

const issues = [];
const deadUrls = [];
const serpMatched = [];
const serpUnmatched = [];

// SERP 도메인 추출 (교차 대조용)
const serpDomains = new Set();
for (const url of serpUrls) {
  try { serpDomains.add(new URL(url).hostname); } catch {}
}

/**
 * HTTP 검증 — try/catch 패턴 (axios 기반)
 * 성공(2xx) = 반환값 존재, 실패(4xx/5xx/타임아웃) = 예외 발생
 */
async function checkUrl(url) {
  // 형식 검증 (HTTP 스킵)
  if (url.includes('...') || url.includes(' ')) {
    return { url, status: 'broken_format' };
  }
  if (url.includes('contoso.com') || url.includes('example.com')) {
    return { url, status: 'placeholder' };
  }

  // HEAD 시도
  try {
    await helpers.httpRequest({
      method: 'HEAD',
      url: url,
      timeout: 5000,
    });
    return { url, status: 'ok' };
  } catch {
    // HEAD 실패 → GET 폴백 (일부 서버 HEAD 거부)
    try {
      await helpers.httpRequest({
        method: 'GET',
        url: url,
        timeout: 5000,
        maxContentLength: 1024,
      });
      return { url, status: 'ok' };
    } catch {
      return { url, status: 'dead' };
    }
  }
}

// 병렬 검증 (배치 5개)
const results = [];
for (let i = 0; i < allUrls.length; i += 5) {
  const batch = allUrls.slice(i, i + 5);
  const batchResults = await Promise.all(batch.map(checkUrl));
  results.push(...batchResults);
}

// 결과 분류
for (const r of results) {
  if (r.status === 'placeholder') continue;

  if (r.status === 'broken_format' || r.status === 'dead') {
    issues.push(`접근 불가: ${r.url}`);
    deadUrls.push(r.url);
  }

  // SERP 교차 대조
  try {
    const domain = new URL(r.url).hostname;
    if (serpDomains.has(domain)) {
      serpMatched.push(r.url);
    } else {
      serpUnmatched.push(r.url);
    }
  } catch {}
}

// 죽은 URL 제거: [텍스트](deadUrl) → 텍스트
let cleanedContent = content;
for (const deadUrl of deadUrls) {
  const escaped = deadUrl.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  cleanedContent = cleanedContent.replace(
    new RegExp(`\\[([^\\]]+)\\]\\(${escaped}\\)`, 'g'),
    '$1'
  );
}

// 죽은 URL을 references에서도 제거
const cleanedReferences = references.filter(ref => {
  if (!ref.startsWith('http')) return true;
  return !deadUrls.includes(ref);
});

const passed = deadUrls.length === 0;

return [{
  json: {
    ...item,
    content: cleanedContent,
    references: cleanedReferences,
    url_validation: {
      passed,
      total_urls: allUrls.length,
      reachable: results.filter(r => r.status === 'ok').length,
      dead: deadUrls.length,
      serp_matched: serpMatched.length,
      serp_unmatched: serpUnmatched.length,
      issues,
    }
  }
}];

/**
 * Node 7b: 코드 블록 기초 포맷 검사
 * 언어 태그 존재 여부, 닫히지 않은 블록 감지
 */

const content = $input.item.json.content;

const issues = [];

// 1. 코드 블록 추출 (열기/닫기 쌍)
const openBlocks = (content.match(/```/g) || []).length;
if (openBlocks % 2 !== 0) {
  issues.push("닫히지 않은 코드 블록 존재");
}

// 2. 언어 태그 없는 코드 블록 감지
const codeBlockRegex = /```(\w*)\n/g;
let match;
let blockCount = 0;
let noTagCount = 0;

while ((match = codeBlockRegex.exec(content)) !== null) {
  blockCount++;
  if (!match[1]) {
    noTagCount++;
  }
}

if (noTagCount > 0) {
  issues.push(`언어 태그 없는 코드 블록: ${noTagCount}/${blockCount}건`);
}

// 3. 허용 언어 태그 검증
const allowedLangs = [
  "powershell", "bash", "cmd", "python", "json", "xml", "yaml",
  "csharp", "javascript", "html", "sql", "text", "plaintext",
  "shell", "ps1", "bat",
];
const langRegex = /```(\w+)/g;
let langMatch;
while ((langMatch = langRegex.exec(content)) !== null) {
  const lang = langMatch[1].toLowerCase();
  if (!allowedLangs.includes(lang)) {
    issues.push(`비표준 언어 태그: ${langMatch[1]}`);
  }
}

const passed = issues.length === 0;

return {
  json: {
    ...$input.item.json,
    code_lint: {
      passed,
      block_count: blockCount,
      issues,
    }
  }
};

/**
 * Build Verify Request — 검증용 system_prompt/user_message 생성
 * 입력: 파싱된 콘텐츠 (title, content 등)
 * 출력: system_prompt, user_message, _llm_purpose + 원본 데이터 패스스루
 */

const title = $input.item.json.title || '';
const content = $input.item.json.content || '';

return {
  json: {
    ...$input.item.json,
    system_prompt: '당신은 B2B IT 기술 콘텐츠 품질 검증 AI입니다. 아래 블로그 글을 검토하고, 정확히 다섯 항목을 평가하세요. 반드시 JSON 형식으로만 응답: {"is_accurate": true/false, "is_logical": true/false, "is_complete": true/false, "is_useful": true/false, "is_in_depth": true/false, "quality_score": 0-100, "reason": "사유 100자 이내"}',
    user_message: `제목: ${title}\n본문:\n${content}`,
    _llm_purpose: 'verification',
  }
};

/**
 * Build LLM Request (Verify) — provider별 URL/headers/body 생성
 * verification용: maxTokens=800, temperature=0
 */

const provider = $env.LLM_PROVIDER || 'gemini';
const systemPrompt = $input.item.json.system_prompt;
const userMessage = $input.item.json.user_message;
const purpose = $input.item.json._llm_purpose || 'content_gen';

const PROVIDERS = {
  gemini: {
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${$env.GOOGLE_API_KEY}`,
    headers: { 'content-type': 'application/json' },
    body: (sys, user, opts) => ({
      contents: [{ role: 'user', parts: [{ text: user }] }],
      systemInstruction: { parts: [{ text: sys }] },
      generationConfig: { maxOutputTokens: opts.maxTokens, temperature: opts.temperature }
    }),
  },
  claude: {
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.CLAUDE_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: (sys, user, opts) => ({
      model: opts.model || 'claude-sonnet-4-5-20250514',
      max_tokens: opts.maxTokens,
      temperature: opts.temperature,
      system: sys,
      messages: [{ role: 'user', content: user }],
    }),
  },
};

const config = PROVIDERS[provider];
if (!config) throw new Error(`지원하지 않는 LLM provider: ${provider}`);

const opts = purpose === 'verification'
  ? { maxTokens: 800, temperature: 0, model: 'claude-haiku-4-5-20251001' }
  : { maxTokens: 32768, temperature: 0.7 };

return {
  json: {
    _llm_url: config.url,
    _llm_headers: config.headers,
    _llm_body: config.body(systemPrompt, userMessage, opts),
    _llm_provider: provider,
    ...Object.fromEntries(
      Object.entries($input.item.json).filter(([k]) => !k.startsWith('_llm'))
    ),
  }
};

/**
 * Normalize LLM Response (Verify) — provider별 응답에서 텍스트 추출
 * Gemini: candidates[0].content.parts[0].text
 * Claude: content[0].text
 */

const provider = $input.item.json._llm_provider
  || $env.LLM_PROVIDER
  || 'gemini';

let text;
const data = $input.item.json;

if (provider === 'gemini') {
  text = data.candidates[0].content.parts[0].text;
} else if (provider === 'claude') {
  text = data.content[0].text;
} else {
  throw new Error(`지원하지 않는 provider 응답: ${provider}`);
}

return { json: { text, _llm_provider: provider } };

/**
 * Node 8: LLM 교차 검증 결과 파싱
 * Mode: runOnceForEachItem
 * 입력: 정규화된 LLM 응답 (text)
 * 출력: 검증 통과/실패 판정 (5항목 + quality_score)
 */

const raw = $input.item.json.text;

// JSON 문자열 정리 (제어 문자 + 유효하지 않은 이스케이프 복구)
function sanitizeJsonStrings(str) {
  const VALID_ESCAPES = '"\\\/bfnrtu';
  let result = '';
  let inString = false;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (inString) {
      if (ch === '\\' && i + 1 < str.length) {
        const next = str[i + 1];
        if (VALID_ESCAPES.includes(next)) {
          result += ch + next;
        } else {
          result += '\\\\' + next;
        }
        i++;
        continue;
      }
      if (ch === '"') {
        inString = false;
        result += ch;
        continue;
      }
      const code = ch.charCodeAt(0);
      if (code <= 0x1f) {
        if (code === 0x0a) result += '\\n';
        else if (code === 0x0d) result += '\\r';
        else if (code === 0x09) result += '\\t';
        continue;
      }
      result += ch;
    } else {
      if (ch === '"') inString = true;
      result += ch;
    }
  }
  return result;
}

// JSON 추출 (방어적 파싱)
let result;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) {
    throw new Error("JSON 없음");
  }
  let jsonStr = sanitizeJsonStrings(match[0]);
  // 구조 복구: 후행 쉼표 제거
  jsonStr = jsonStr.replace(/,\s*([}\]])/g, '$1');
  result = JSON.parse(jsonStr);
} catch (e) {
  // LLM 파싱 실패 시 검수필요로 분류
  return {
    json: {
      ...$input.item.json,
      verification: {
        passed: false,
        is_accurate: null,
        is_logical: null,
        is_complete: null,
        is_useful: null,
        quality_score: 0,
        reason: `LLM 응답 파싱 실패: ${e.message}`,
        raw_response: raw.substring(0, 300),
      }
    }
  };
}

// 필수 필드 검증 (기존 2항목은 필수, 신규 2항목은 기본값 처리)
if (typeof result.is_accurate !== "boolean" || typeof result.is_logical !== "boolean") {
  return {
    json: {
      ...$input.item.json,
      verification: {
        passed: false,
        is_accurate: result.is_accurate ?? null,
        is_logical: result.is_logical ?? null,
        is_complete: result.is_complete ?? null,
        is_useful: result.is_useful ?? null,
        quality_score: result.quality_score ?? 0,
        reason: "검증 결과 형식 오류 (boolean 아님)",
      }
    }
  };
}

// 신규 항목 기본값 (LLM이 누락하면 true로 간주 — 하위 호환)
const isComplete = typeof result.is_complete === "boolean" ? result.is_complete : true;
const isUseful = typeof result.is_useful === "boolean" ? result.is_useful : true;
const isInDepth = typeof result.is_in_depth === "boolean" ? result.is_in_depth : true;
const qualityScore = typeof result.quality_score === "number" ? result.quality_score : 0;

const MIN_QUALITY_SCORE = 70;
const passed = result.is_accurate === true
  && result.is_logical === true
  && isComplete === true
  && isUseful === true
  && isInDepth === true
  && qualityScore >= MIN_QUALITY_SCORE;

return {
  json: {
    ...$input.item.json,
    verification: {
      passed,
      is_accurate: result.is_accurate,
      is_logical: result.is_logical,
      is_complete: isComplete,
      is_useful: isUseful,
      is_in_depth: isInDepth,
      quality_score: qualityScore,
      reason: result.reason || "",
    }
  }
};
